import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        double C = Double.parseDouble(st.nextToken());

        double[][] items = new double[n][2];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            items[i][0] = Double.parseDouble(st.nextToken());
            items[i][1] = Double.parseDouble(st.nextToken());
        }
        Arrays.sort(items, (a, b) -> Double.compare(b[1] / b[0], a[1] / a[0]));

        double total = 0;
        double remain = C;
        for (double[] item : items) {
            if (remain <= 0) break;
            double take = Math.min(item[0], remain);
            total += take * (item[1] / item[0]);
            remain -= take;
        }
        System.out.printf("%.2f%n", total);
    }
}

