int main(){

    int n; double C; cin>>n>>C;

    vector<pair<double,double>> items(n);

    for(auto&[w,v]:items) cin>>w>>v;

    sort(items.begin(),items.end(),[](auto&a,auto&b){return a.second/a.first>b.second/b.first;});

    double total=0,remain=C;

    for(auto&[w,v]:items){

        if(remain<=0) break;

        double take=min(w,remain);

        total+=take*(v/w); remain-=take;

    }

    printf("%.2f\n",total);

